import{_ as i,l as s,o as a,c as o,v as r,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"全文检索引擎","description":"","frontmatter":{"title":"全文检索引擎","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/search-engine-index.md","filePath":"cs/search-engine-index.md","lastUpdated":1789023840000}'),h={name:"cs/search-engine-index.md"};function E(_,e,m,u,f,B){const n=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="全文检索引擎" tabindex="-1">全文检索引擎 <a class="header-anchor" href="#全文检索引擎" aria-label="Permalink to &quot;全文检索引擎&quot;">​</a></h1><div class="epigraph"><p>独立搜索引擎把倒排段、打分、分片做成集群：近实时可见靠刷新，不是 SQL 提交即搜。库内 GIN 是子集。</p><footer>—— 据 Lucene 架构；Manning IR；倒排课的集群落地</footer></div><p><a href="/cs/vector-db-ann">上一课</a>可与全文混合。本课专搜索引擎：Elasticsearch/Lucene 一族。缺口是相对库内全文：刷新间隔、副本分片、评分相关性、与主库 CDC 对齐。事务课的 D 在这里常是「近实时」，RPO 按刷新与 translog。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文档进缓冲，refresh 成可搜段，search 多段归并，merge 后台——LSM 同构。缺口是 <strong>SQL 事务 vs 可搜</strong>：未 refresh 的文档搜不到，应用若以为提交即搜会错。CDC 从库到引擎是异步，读己之写要等 refresh 或搜主库。</p><p>分片：文档 id 哈希， scatter 查询再合并打分——分布式 top-k。相关性：BM25 在引擎，SQL <code>ORDER BY</code> 不是同一回事。</p><p><span class="marginnote">Lucene 段与 translog。本课集群合同。库内倒排课已有 posting。向量可作为 Lucene 字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>索引模板、mapping（分析器）。查询 DSL。与关系：主键同步、死信重试。权限：字段级安全 vs 后课行级安全在库。</p><p>容量：倒排内存、doc values 列存给排序聚合——引擎内 HTAP 雏形。</p>',10)),(a(),l(p,null,{default:t(()=>[c(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDX%5B%22index%20%E7%BC%93%E5%86%B2%22%5D%20--%3E%20REF%5B%22refresh%20%E6%88%90%E6%AE%B5%22%5D%0A%20%20REF%20--%3E%20SCH%5B%22%E5%A4%9A%E6%AE%B5%E6%A3%80%E7%B4%A2%E6%89%93%E5%88%86%22%5D%0A%20%20REF%20--%3E%20MRG%5B%22merge%22%5D%0A%20%20DB%5B%22%E4%B8%BB%E5%BA%93%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20CDC%5B%22%E5%BC%82%E6%AD%A5%E5%88%B0%E5%BC%95%E6%93%8E%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性：副本等待可配，类似半同步。脑裂有选举。Jepsen 后课对搜索集群也测过丢失。优化：filter 上下文走位图缓存，query 上下文打分。</p><p>与 zone：段上的 doc 值 min/max 跳过。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SQLite 页。也不把搜索当唯一真相库——主库仍权威。湖仓分析另一路。</p><p>后课默认：全文集群近实时；提交即搜要等或走库。SQLite 架构：嵌入式整库一份文件，另一极端。</p><p>搜索引擎是特化执行器+倒排存储，不是 Selinger 的通用 SQL。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>段+refresh+merge 近实时可搜；与 SQL 提交不同步除非等待。</li><li>分片 scatter 打分；CDC 对齐主库。</li><li>SQLite 架构下一课。</li><li>出处：Lucene；Manning IR；LSM 对照。</li></ul>',9))])}const g=i(h,[["render",E]]);export{S as __pageData,g as default};
